{
  "name": "@sub2tok/magpie",
  "version": "0.1.6",
  "description": "magpie provider plugin for sub2tok: models, balance and exclusive subscription quotas with one API token",
  "type": "module",
  "exports": {
    ".": "./dist/index.mjs"
  },
  "scripts": {
    "build": "esbuild src/index.ts --format=esm --platform=neutral --target=es2022 --outfile=dist/index.mjs",
    "prepublishOnly": "npm run build"
  },
  "files": [
    "dist/index.mjs",
    "README.md",
    "README.en.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-plugin",
    "provider",
    "sub2tok"
  ],
  "license": "MIT",
  "homepage": "https://sub2tok.com",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "magpie": {
    "icon": "data:image/svg+xml;base64,",
    "maxConcurrency": 16,
    "options": {
      "baseURL": "https://api.sub2tok.com"
    }
  },
  "devDependencies": {
    "esbuild": "^0.28.2"
  }
}
